  start(source){var s=this.state;if(s.current&&s.current.cleanup!=='清理完成')return;if(!source&&(!s.version||s.scene!=='valid'||!s.attached||s.version.sceneEpoch!==s.capturedEpoch||s.caseId!=='C1'))return;var attempt=source?0:1;var id=(source?'verify-demo-':'run-demo-')+String(s.runNo+1).padStart(3,'0');var sourceVersion=source?s.versions.find(v=>v.id===source.taskVersion):s.version;var copy=Object.assign({},s,{version:sourceVersion,caseId:source?source.caseId:s.caseId,attempt:attempt,elapsed:0});var record=this.newRecord(copy,id,source);var runVersion=sourceVersion;if(source){record.completeSource=true;record.mode='无模型复验';record.sourceRunId=source.id;record.taskVersion=source.taskVersion;record.goal=source.goal;}this.setState({maxAttempts:runVersion.maxAttempts,maxMinutes:runVersion.maxMinutes,caseId:source?source.caseId:s.caseId,version:runVersion,phase:source?'reverifying':'modifying',attempt:attempt,elapsed:0,runNo:s.runNo+1,current:record,tab:'report',module:'space',cleanup:'运行中',command:source?'不运行修改命令':'运行中',ready:false,events:this.event(source?'新建 '+id+'；使用 '+source.id+' 的完整最终源码；模型调用 0':'新建 '+id+'；开始 Agent 修改演示')});}
  finish(result,phase){var s=this.state;var record=Object.assign({},s.current,{result:result,review:s.current.sourceRunId?'不适用（复验）':result==='通过'?'待审阅':'不适用（未通过）',completeSource:result==='通过',cleanup:'清理完成',attempt:s.attempt,elapsed:s.elapsed+45,attempts:(s.current.attempts||[]).concat({number:s.attempt,result:result})});var history=s.history.filter(r=>r.id!==record.id).concat(record);this.setState({phase:phase,current:record,history:history,cleanup:'清理完成',elapsed:s.elapsed+45,events:this.event((result==='已取消'?'运行已取消；固定检查未完成':'固定检查 '+result)+'；进程清理完成；用户决定 '+record.review)});}
  advance(){var s=this.state;if(s.current&&s.current.mode==='在线演示'&&['modifying','command','waiting','ready','checking'].indexOf(s.phase)>=0&&s.elapsed+45>s.maxMinutes*60){this.inject('timeout');return;}var transitions={modifying:'command',command:'waiting',waiting:'ready',ready:'checking'};if(transitions[s.phase]){var next=transitions[s.phase];this.setState({phase:next,elapsed:s.elapsed+40,command:next==='command'?'exit 0':s.command,ready:next==='ready'||s.ready,events:this.event({command:'修改命令 exit 0；服务尚未就绪',waiting:'等待服务就绪信号',ready:'服务就绪；固定检查尚未执行',checking:'独立验收浏览器开始固定检查'}[next])});return;}if(s.phase==='checking'||s.phase==='reverifying'){this.finish('通过','passed');return;}if(s.phase==='failedCleanup'){this.finish('失败','failedStopped');this.setState({command:'已退出'});return;}if(s.phase==='cancelling'){this.finish('已取消','cancelled');this.setState({command:'已退出'});return;}if(['tool','startup','timeout'].indexOf(s.phase)>=0&&s.cleanup!=='清理完成'){var record=Object.assign({},s.current,{cleanup:'清理完成'});this.setState({cleanup:'清理完成',current:record,history:s.history.filter(r=>r.id!==record.id).concat(record),events:this.event('清理回执已收到；恢复入口可用')});}}
