  recordDetail(record){if(!record)return '尚无运行记录。';return 'runId: '+record.id+'\n任务版本: '+record.taskVersion+'\n模式: '+record.mode+'\nsourceRunId: '+(record.sourceRunId||'无（在线来源记录）')+'\n最终源码: '+(record.completeSource?'完整源码快照（设计模拟）':'不存在完整可读源码快照')+'\nsourceHash: '+(record.completeSource?record.sourceHash:'不可用')+'\nacceptanceHash: '+record.acceptanceHash+'\n模型调用: '+record.modelCalls+'\n结果: '+record.result+'\n清理: '+record.cleanup+'\n用户决定: '+record.review+'\n预算累计: '+this.time(record.elapsed)+'\n示例快照包含完整模板目录、API、UI、数据迁移与固定验收版本；非仅 diff。';}
